def migrar_ventas_v1(apps, schema_editor):
    """Completa las ventas de la v1: precio de cada línea, total y anulaciones."""
    Venta = apps.get_model('inventario', 'Venta')
    Salida = apps.get_model('inventario', 'SalidaInventario')

    # La v1 no guardaba el precio: se usa el precio actual del producto
    for salida in Salida.objects.filter(precio_unitario__isnull=True).select_related('producto'):
        salida.precio_unitario = salida.producto.precio or Decimal('0.00')
        salida.save(update_fields=['precio_unitario'])

    for venta in Venta.objects.all():
        lineas = Salida.objects.filter(venta=venta)
        borradas = lineas.filter(is_deleted=True)
        if venta.anulada:
            # En la v1, borrar una venta no devolvía el stock
            venta.motivo_anulacion = 'Borrada en la versión 1 (el stock no se devolvió)'
        elif borradas.exists() and not lineas.filter(is_deleted=False).exists():
            venta.anulada = True
            venta.motivo_anulacion = 'Borrada en la versión 1'
        elif borradas.exists():
            # Líneas sueltas borradas en la v1: su stock ya se devolvió, dejan de contar
            borradas.delete()
        vivas = lineas if venta.anulada else lineas.filter(is_deleted=False)
        venta.total = sum((l.precio_unitario * l.cantidad for l in vivas), Decimal('0.00'))
        venta.save(update_fields=['anulada', 'motivo_anulacion', 'total'])


